cats={"needle-sinker":{"en":"Needle & sinker","bn":"সুই ও সিঙ্কার"},"yarn":{"en":"Yarn & feeding","bn":"সুতা ও ফিডিং"},"contamination":{"en":"Contamination","bn":"দূষণ"},"tension":{"en":"Tension & take-down","bn":"টেনশন ও টেক-ডাউন"},"appearance":{"en":"Appearance & dimensions","bn":"চেহারা ও মাপ"}}
ids={x["id"] for x in D}
for x in D:
    assert all(r in ids for r in x["related"]),(x["id"],x["related"])
    for k in("symptoms","causes","diagnostic","inspection","actions","verify"):
        assert len(x[k]["en"])==len(x[k]["bn"]),(x["id"],k)
json.dump({"categories":cats,"defects":D},open("src/data/defects.json","w",encoding="utf-8"),ensure_ascii=False,indent=1)
print(len(D),"defects")
